-------------------------
---- TINTY / COLORS ----
-------------------------

-- Generated by tinty's base16-hyprland-lua item (~/.config/tinty/config.toml);
-- ships as a static base16-onedark default in skel so this is always
-- present regardless of whether tinty-git has actually built/installed
-- yet.
local colors = require("colors")

-- Hyprland's own color fields need "rgba(RRGGBBAA)"/"rgb(RRGGBB)" (hex
-- digits in parens, no `#`), but colors.lua's values are plain
-- '#RRGGBB' strings -- confirmed directly against Hyprland's own Lua
-- color-field parser, which only accepts the parens form.
local function rgb(hex)
	return "rgb(" .. hex:sub(2) .. ")"
end
local function rgba(hex, alpha)
	return "rgba(" .. hex:sub(2) .. alpha .. ")"
end

