-- Generic fallback: matches any monitor not covered by a machine-specific rule below.
hl.monitor({
	output = "",
	mode = "preferred",
	position = "auto",
	scale = "auto",
})

-- Machine-specific monitor layout and workspace pinning. Not tracked by the dotfiles/distro defaults; safe to be absent.
pcall(dofile, os.getenv("HOME") .. "/.config/hypr/local.lua")

-- NVIDIA-specific env vars, deployed only on machines where hardware
-- detection found an NVIDIA GPU (see installer/archinstall/nvidia.lua).
-- Safe to be absent on AMD/Intel-only systems.
pcall(dofile, os.getenv("HOME") .. "/.config/hypr/nvidia.lua")

-------------------
---- AUTOSTART ----
-------------------

hl.on("hyprland.start", function()
	hl.exec_cmd("systemctl --user start hyprpolkitagent")
	hl.exec_cmd("waybar & mako & hypridle & hyprpaper & udiskie")
	hl.exec_cmd("fcitx5")
	hl.exec_cmd("xdg-user-dirs-update")
	-- `tinty-git` is base-required (always installed), but `command -v`
	-- guards anyway: an already-installed system only picks up a newly
	-- base-required package once its "Update Config" flow runs, and a
	-- package build can always fail. `tinty list` is empty until `tinty
	-- install` has cloned/built the scheme and template repos declared
	-- in config.toml; nothing else in sobarch ever runs that, so it's
	-- done here, once, self-healing on every login rather than gated
	-- behind a marker file: cheap to re-check (`tinty list` is local, no
	-- network) and correct even if a prior attempt was interrupted (e.g.
	-- no network yet at login).
	-- `tinty init` (re-applies the last-applied or default scheme)
	-- still runs every login same as before.
	hl.exec_cmd("command -v tinty >/dev/null 2>&1 && { tinty list | grep -q . || tinty install; tinty init; }")
end)

hl.exec_cmd('gsettings set org.gnome.desktop.interface gtk-theme "adw-gtk3"')
hl.exec_cmd('gsettings set org.gnome.desktop.interface color-scheme "prefer-dark"')
hl.exec_cmd('gsettings set org.gnome.desktop.interface icon-theme "Papirus-Dark"')

