--------------------------------
---- WINDOWS AND WORKSPACES ----
--------------------------------

hl.window_rule({
	name = "suppress-maximize-events",
	match = { class = ".*" },
	suppress_event = "maximize",
})

hl.window_rule({
	name = "fix-xwayland-drags",
	match = {
		class = "^$",
		title = "^$",
		xwayland = true,
		float = true,
		fullscreen = false,
		pin = false,
	},
	no_focus = true,
})

hl.window_rule({
	name = "float-network-manager",
	match = { title = ".*Network Manager.*" },
	float = true,
})

hl.layer_rule({
	name = "no-anim-fuzzel",
	match = { namespace = "^(fuzzel)$" },
	no_anim = true,
})
